// generate-pgboss-migration.js: writes the numbered SQL migration that installs (or upgrades)
// pg-boss's `pgboss` schema, so it is created by resolvd_owner through the normal migration runner
// and the API can run pg-boss as resolvd_app with its automatic migrations turned off.
//
//   node scripts/generate-pgboss-migration.js
//
// First run: install SQL from getConstructionPlans(). Later runs (after upgrading pg-boss): upgrade
// SQL from getMigrationPlans(), starting at the schema version recorded in the newest pgboss
// migration. Commit the generated file like any other migration; never edit an applied one.
import { readdir, readFile, writeFile } from 'node:fs/promises';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { getConstructionPlans, getMigrationPlans } from 'pg-boss';

const MIGRATIONS_DIR = path.resolve(
  path.dirname(fileURLToPath(import.meta.url)),
  '../db/migrations',
);
const SCHEMA = 'pgboss';
const VERSION_MARKER = /^-- pgboss-schema-version: (\d+)$/m;

/** Installed pg-boss's schema version (package.json "pgboss.schema"). */
async function packageSchemaVersion() {
  const pkgPath = path.resolve(
    path.dirname(fileURLToPath(import.meta.url)),
    '../node_modules/pg-boss/package.json',
  );
  const pkg = JSON.parse(await readFile(pkgPath, 'utf8'));
  return { schemaVersion: Number(pkg.pgboss.schema), packageVersion: pkg.version };
}

/**
 * pg-boss plans wrap themselves in BEGIN/COMMIT. The migration runner already runs each file in one
 * transaction (and records it in schema_migrations inside that transaction), so the inner pair is
 * removed. SET LOCAL and pg_advisory_xact_lock keep working inside the runner's transaction.
 * @param {string} sql
 */
function stripOuterTransaction(sql) {
  const lines = sql.split('\n');
  const begin = lines.findIndex((l) => l.trim() === 'BEGIN;');
  const commit = lines.findLastIndex((l) => l.trim() === 'COMMIT;');
  if (begin === -1 || commit === -1 || commit < begin) {
    throw new Error('Unexpected pg-boss plan shape: expected one outer BEGIN; ... COMMIT;');
  }
  lines.splice(commit, 1);
  lines.splice(begin, 1);
  return lines.join('\n').trim();
}

/** Grants that let resolvd_app run pg-boss (DML only; it never owns or alters pg-boss objects). */
function grants() {
  return `-- ----- Runtime access for resolvd_app (pg-boss runs with migrate: false) -----
GRANT USAGE ON SCHEMA ${SCHEMA} TO resolvd_app;
GRANT SELECT, INSERT, UPDATE, DELETE ON ALL TABLES IN SCHEMA ${SCHEMA} TO resolvd_app;
GRANT USAGE, SELECT, UPDATE ON ALL SEQUENCES IN SCHEMA ${SCHEMA} TO resolvd_app;
GRANT EXECUTE ON ALL FUNCTIONS IN SCHEMA ${SCHEMA} TO resolvd_app;`;
}

async function main() {
  const files = (await readdir(MIGRATIONS_DIR)).filter((f) => /^\d{3}_.+\.sql$/.test(f)).sort();
  const lastNumber = Number(files.at(-1)?.slice(0, 3) ?? 0);
  const nextNumber = String(lastNumber + 1).padStart(3, '0');

  // The newest existing pgboss migration tells us which schema version is already installed.
  let installedVersion = null;
  for (const file of files.filter((f) => f.includes('pgboss')).reverse()) {
    const match = VERSION_MARKER.exec(await readFile(path.join(MIGRATIONS_DIR, file), 'utf8'));
    if (match) {
      installedVersion = Number(match[1]);
      break;
    }
  }

  const { schemaVersion, packageVersion } = await packageSchemaVersion();
  if (installedVersion === schemaVersion) {
    console.log(
      `pg-boss schema ${schemaVersion} is already covered by a migration. Nothing to do.`,
    );
    return;
  }

  const install = installedVersion === null;
  const plan = install
    ? getConstructionPlans(SCHEMA, { createSchema: true })
    : getMigrationPlans(SCHEMA, installedVersion);
  const name = install ? 'pgboss' : `pgboss_v${schemaVersion}`;
  const fileName = `${nextNumber}_${name}.sql`;

  const header = `-- ${fileName}: ${install ? 'installs' : 'upgrades'} the pg-boss job queue schema (\`${SCHEMA}\`).
-- GENERATED by scripts/generate-pgboss-migration.js from pg-boss ${packageVersion}; do not edit by hand.
-- Runs as resolvd_owner like every migration. pg-boss tables are not tenant tables (no RLS); workers
-- do all tenant work inside withOrg(). See docs/DECISIONS.md.
-- pgboss-schema-version: ${schemaVersion}`;

  const body = `${header}\n\n${stripOuterTransaction(plan)}\n\n${grants()}\n`;
  await writeFile(path.join(MIGRATIONS_DIR, fileName), body);
  console.log(`Wrote db/migrations/${fileName} (pg-boss schema ${schemaVersion}).`);
}

await main();
